            /** Format: int64 */
            refund_minor: number;
            /** Format: int64 */
            dispute_withdrawn_minor: number;
            /** Format: int64 */
            dispute_reinstated_minor: number;
            /** Format: int64 */
            fee_minor: number;
            /** Format: int64 */
            net_minor: number;
            /** Format: int64 */
            charge_count: number;
            /** Format: int64 */
            refund_count: number;
            /** Format: int64 */
            dispute_count: number;
            /** Format: int64 */
